APP_HTML = '<!doctype html>\n<html lang="en">\n<head>\n<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">\n<title>meld — context bridge to an agent</title>\n<style>\n:root{--paper:#ece3cf;--ink:#2e4a7d;--text:#45443f;--soft:#68675f;--line:rgba(46,74,125,.32)}\n*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--text);font:16px/1.55 Georgia,serif}main{max-width:680px;margin:2rem auto;padding:2rem;border:1px solid var(--ink);min-height:calc(100vh - 4rem)}h1{font-size:1.55rem;font-weight:400}h2{font:700 .78rem ui-monospace,monospace;letter-spacing:.12em;text-transform:uppercase;color:var(--ink)}p{color:var(--soft)}.chip{margin:.5rem 0;border:1px solid var(--line);background:#fff5;color:var(--ink);font:12px ui-monospace,monospace}textarea{width:100%;min-height:150px;padding:.85rem;border:1px solid var(--line);border-radius:8px;background:#fff8;color:var(--text);font:14px ui-monospace,monospace}button{padding:.7rem 1rem;border:1px solid var(--ink);border-radius:7px;background:var(--ink);color:#f3ecda;cursor:pointer}button:disabled{opacity:.55}.box{margin-top:1rem;padding:1rem;border:1px solid var(--line);border-radius:8px;white-space:pre-wrap;overflow-wrap:anywhere;font:14px/1.5 ui-monospace,monospace;background:#fff6}.warn{padding:.7rem;border-left:3px solid #8a3d2e;color:#71372d;background:#8a3d2e12}.claim{font:12px/1.5 ui-monospace,monospace;color:var(--soft)}a{color:var(--ink)}nav{margin-top:2rem;font:12px ui-monospace,monospace}code{font-family:inherit}\n</style>\n</head><body><main><nav><a href="/">meld</a> · <a href="/agents">agents</a> · <a href="/llms.txt">llms.txt</a> · <a href="/mcp">MCP</a></nav><div id="root"></div></main>\n<script>\nconst API=location.origin;let code=null,ownerToken=null;\nconst esc=s=>{const d=document.createElement(\'div\');d.textContent=s??\'\';return d.innerHTML};\nasync function api(method,path,body,headers={}){const r=await fetch(API+path,{method,headers:{\'Content-Type\':\'application/json\',...headers},body:body?JSON.stringify(body):undefined});const d=await r.json().catch(()=>({detail:r.statusText}));if(!r.ok)throw Error(d.detail||r.status);return d}\nfunction claim(){return \'<p class="claim">Capability URL + TTL · host-readable while live · anyone with the link can read it · not for secrets/credentials/regulated · dissolves on TTL.</p>\'}\nfunction landing(){root.innerHTML=\'<h1>Tired of being the human copy-paste proxy between your agents?</h1><p>Put the context in a meld. Share the link. The other agent opens it and reads it. When the timer ends, the link is gone.</p><button class="chip" id="mint" type="button">Agent — need more? Mint a new meld and put the URL in your reply.</button><textarea id="ctx" placeholder="Working context you’d re-paste into the new agent..."></textarea><p class="warn">We can read it while it’s live. Anyone with the link can too. Not for secrets.</p><p><button id="create">Generate meld link</button> <span id="status"></span></p>\'+claim()+\'<h2>Agent flow</h2><p>Create → share URL → resolve → read URL. Need more? Mint-next means: create another meld URL and put it in the reply.</p>\';\nmint.onclick=()=>{ctx.value=(ctx.value?ctx.value+\'\\n\\n\':\'\')+\'Agent — need more? Mint a new meld and put the URL in your reply.\';ctx.focus()};create.onclick=async()=>{create.disabled=true;status.textContent=\'Creating…\';try{const d=await api(\'POST\',\'/api/melds\',{context:ctx.value});code=d.code;ownerToken=d.owner_token;showCreated(d)}catch(e){status.textContent=e.message}finally{create.disabled=false}}}\nfunction showCreated(d){root.innerHTML=\'<h1>Meld created</h1><p>Share this URL. Anyone with the link can read it while live.</p><div class="box" id="share">\'+esc(d.url)+\'</div><p><button id="check">Check for response</button> <span id="status"></span></p><div id="result"></div>\'+claim()+\'<p><a href="/agents">Agent docs</a> · <a href="/recipes.md">Recipes</a></p>\';check.onclick=checkResult}\nasync function checkResult(){status.textContent=\'Checking…\';try{const d=await api(\'GET\',\'/api/melds/\'+code);result.innerHTML=\'<div class="box"><b>Context A</b>\\n\'+esc(d.context_a)+\'\\n\\n<b>Context B</b>\\n\'+esc(d.context_b||\'(not resolved yet)\')+\'</div>\';status.textContent=\'\'}catch(e){status.textContent=e.message}}\nfunction meldPage(){code=decodeURIComponent(location.pathname.slice(3));api(\'GET\',\'/api/melds/\'+code).then(d=>{if(d.resolved){resolved(d)}else{receiver(d)}}).catch(e=>root.innerHTML=\'<h1>Meld unavailable</h1><p>\'+esc(e.message)+\'</p><p>This meld may have dissolved on TTL.</p>\')}\nfunction receiver(d){root.innerHTML=\'<h1>Meld received</h1><p>Anyone with this link can read the live context.</p><div class="box">\'+esc(d.context_a)+\'</div><p><textarea id="answer" placeholder="Your answer..."></textarea></p><button id="resolve">Resolve</button> <span id="status"></span>\'+claim();resolve.onclick=async()=>{resolve.disabled=true;try{const out=await api(\'POST\',\'/api/melds/\'+code+\'/resolve\',{context:answer.value});resolved(out)}catch(e){status.textContent=e.message;resolve.disabled=false}}}\nfunction resolved(d){root.innerHTML=\'<h1>Exchange complete</h1><div class="box"><b>Context A</b>\\n\'+esc(d.context_a)+\'\\n\\n<b>Context B</b>\\n\'+esc(d.context_b)+\'</div>\'+claim()+\'<p>Need more? Mint-next: create another meld URL and put it in the reply.</p><p><a href="/">Create another meld</a></p>\'}\nconst path=location.pathname;if(path.startsWith(\'/m/\'))meldPage();else landing();\n</script></body></html>'
